add_filter( 'the_title', 'perfectpixel_new_badge_recent_posts', 20, 2 );

function perfectpixel_new_badge_recent_posts( $title, $post_id = 0 ) {
	if ( is_admin() || ! $post_id || ! in_the_loop() || 'post' !== get_post_type( $post_id ) || is_feed() ) {
		return $title;
	}
	$age = time() - (int) get_post_time( 'U', true, $post_id );
	if ( $age > max( 1, (int) '{{new_post_days}}' ) * DAY_IN_SECONDS ) {
		return $title;
	}
	$color = sanitize_hex_color( '{{new_post_badge_color}}' );
	return $title . ' <span class="perfectpixel-new-badge" style="display:inline-block;vertical-align:middle;margin-left:.4em;padding:.1em .45em;border-radius:3px;font-size:.6em;line-height:1.4;color:#fff;background:' . esc_attr( $color ? $color : '#d63638' ) . '">' . esc_html( '{{new_post_badge_text}}' ) . '</span>';
}
